const listProductsV2 = `-- name: ListProductsV2 :many

SELECT
    p.id, p.workspace_id, p.name, p.description, p.kind, p.status, p.unit_name,
    p.short_description, p.long_description, p.image_urls, p.archived_at,
    p.created_at, p.updated_at,
    v.id AS default_variant_id, v.sku, v.barcode, v.selling_price_minor, v.cost_price_minor,
    v.compare_at_price_minor, v.currency, v.currency_exponent,
    COALESCE((SELECT SUM(b.quantity_on_hand) FROM inventory_balances b
              WHERE b.workspace_id = p.workspace_id AND b.product_id = p.id), 0)::numeric AS quantity_on_hand,
    GREATEST((SELECT COUNT(*) FROM product_variants pv
      WHERE pv.workspace_id = p.workspace_id AND pv.product_id = p.id AND pv.is_active AND pv.archived_at IS NULL AND pv.is_default = false), 1)::bigint AS variant_count,
    COALESCE((
        SELECT array_agg(ci.collection_id ORDER BY ci.collection_id)
        FROM product_collection_items ci
        WHERE ci.workspace_id = p.workspace_id AND ci.product_id = p.id
    ), '{}')::bigint[] AS collection_ids
FROM products p
JOIN product_variants v ON v.product_id = p.id AND v.workspace_id = p.workspace_id AND v.is_default = true
WHERE p.workspace_id = $1
  AND ($2::text IS NULL OR p.name ILIKE '%' || $2::text || '%' OR v.sku ILIKE '%' || $2::text || '%')
  AND ($3::text IS NULL OR p.status = $3::text)
  AND ($4::text IS NULL OR p.kind = $4::text)
  AND ($5::bigint IS NULL OR EXISTS (
        SELECT 1 FROM product_collection_items ci
        WHERE ci.workspace_id = p.workspace_id AND ci.product_id = p.id AND ci.collection_id = $5::bigint))
  AND ($6::bigint IS NULL OR p.id < $6::bigint)
ORDER BY p.id DESC
LIMIT $7
`

