// Products v2: product detail, edits, outlets, collections, history and imports.
func (q *Queries) ListProductsV2(ctx context.Context, arg ListProductsV2Params) ([]ListProductsV2Row, error) {
	rows, err := q.db.Query(ctx, listProductsV2,
		arg.WorkspaceID,
		arg.Search,
		arg.Status,
		arg.Kind,
		arg.CollectionID,
		arg.BeforeID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListProductsV2Row{}
	for rows.Next() {
		var i ListProductsV2Row
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Name,
			&i.Description,
			&i.Kind,
			&i.Status,
			&i.UnitName,
			&i.ShortDescription,
			&i.LongDescription,
			&i.ImageUrls,
			&i.ArchivedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DefaultVariantID,
			&i.Sku,
			&i.Barcode,
			&i.SellingPriceMinor,
			&i.CostPriceMinor,
			&i.CompareAtPriceMinor,
			&i.Currency,
			&i.CurrencyExponent,
			&i.QuantityOnHand,
			&i.VariantCount,
			&i.CollectionIds,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

